=📋 *Nueva pieza para revisar* (registro `{{ $json.recordId }}`)
*Idea semilla:* {{ $json.idea }}
*Categoría:* {{ $json.categoria }}  ·  *Canal destino:* {{ $json.canal }}

*Borrador generado por IA:*
>>> {{ $json.contenido }}

parameters.jsCode:
// Convierte cualquier fallo del flujo principal en un payload estándar para SUB 4.
const reg = $('🧹 Normalizar registro').first().json;
const origen = $prevNode.name;
const e = $json.error;
let mensaje;
if (origen === '❓ ¿Datos completos?') {
  const faltantes = [];
  if (!reg.idea) faltantes.push('Idea Semilla vacía');
  if (!reg.categoria) faltantes.push('Categoria vacía');
  if (reg.idea && reg.longitudIdea < reg.cfg.minCaracteresIdea) {
    faltantes.push(`Idea Semilla demasiado corta (${reg.longitudIdea} < ${reg.cfg.minCaracteresIdea} caracteres)`);
  }
  mensaje = 'Datos faltantes/incompletos: ' + faltantes.join('; ');
} else if (typeof e === 'string') {
  mensaje = e;
} else {
  mensaje = e?.message || e?.description || JSON.stringify($json);
}
return [{
  json: {
    subflujo: 'registrar_error',
    recordId: reg.recordId,
    idea: reg.idea,
    modulo: origen === '❓ ¿Datos completos?' ? 'Validación de entrada' : origen,
    mensaje: String(mensaje).slice(0, 1000),
    cfg: reg.cfg,
  },
}];

// Une los fragmentos validados del Manual de Marca y arma el prompt dinámico.
// Minimización de datos: al modelo solo viajan idea, categoría, canal y el contexto RAG.
const ctx = $('🔀 Router de subworkflows').first().json;
const cfg = ctx.cfg;
const fragmentos = $input.all()
  .map(i => i.json)
  .filter(r => r && (r['Contenido Validado'] || r.fields?.['Contenido Validado']))
  .map(r => {
    const f = r.fields ?? r;
    return `Tema: ${f['Tema'] ?? 's/d'}\n${f['Contenido Validado']}`;
  });

if (fragmentos.length === 0) {
  return [{ json: {
    ...ctx, ok: false,
    modulo: '📚 RAG · Buscar en Manual de Marca',
    mensaje: `Sin contexto validado en el Manual de Marca para la categoría "${ctx.categoria}"`,
  } }];
}

const systemPrompt =
  'Sos el redactor de contenido de la marca. Tu única fuente de verdad es el CONTEXTO VALIDADO ' +
  'que recibís, extraído del Manual de Marca. No uses conocimiento externo ni inventes datos sobre ' +
  `la empresa. Redactá un post para ${ctx.canal}: profesional, cercano y estructurado ` +
  `(hook inicial, cuerpo, cierre con llamada a la acción), de no más de ${cfg.maxPalabras} palabras. ` +
  'Devolvé solo el texto del post, sin comentarios adicionales.';

const userPrompt =
  `Idea semilla: ${ctx.idea}\nCategoría: ${ctx.categoria}\nCanal destino: ${ctx.canal}\n\n` +
  `CONTEXTO VALIDADO DE LA MARCA:\n${fragmentos.join('\n\n')}`;

return [{ json: {
  ...ctx,
  ok: true,
  fragmentosRAG: fragmentos.length,
  geminiBody: {
    system_instruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    generationConfig: { maxOutputTokens: cfg.maxTokens, temperature: cfg.temperatura },
  },
} }];

// Valida la respuesta del modelo (camino infeliz: respuesta vacía, bloqueada o truncada).
const ctx = $('🧠 Unir contexto + armar prompt').first().json;
const cand = $json.candidates?.[0];
const texto = (cand?.content?.parts ?? []).map(p => p.text ?? '').join('').trim();
const palabras = texto ? texto.split(/\s+/).length : 0;
const usage = $json.usageMetadata ?? {};
const { geminiBody, ...resto } = ctx;
return [{ json: {
  ...resto,
  ok: palabras > 0,
  contenido: texto,
  palabras,
  finishReason: cand?.finishReason ?? 'SIN_CANDIDATOS',
  tokensEntrada: usage.promptTokenCount ?? 0,
  tokensSalida: usage.candidatesTokenCount ?? 0,
  modulo: '🤖 IA · Gemini genera borrador',
  mensaje: palabras > 0 ? '' : `La IA no devolvió texto (finishReason: ${cand?.finishReason ?? 'SIN_CANDIDATOS'})`,
} }];

// Estandariza cualquier fallo ocurrido dentro de SUB 1/2/3 para registrarlo en SUB 4.
const ctx = $('🔀 Router de subworkflows').first().json;
// Si el item trae "error" viene de una salida de error de nodo; si no, de una validación (IF false).
const e = $json.error;
let modulo, mensaje;
if (e) {
  modulo = $prevNode.name;
  mensaje = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
} else {
  modulo = $json.modulo || $prevNode.name;
  mensaje = $json.mensaje || 'Validación fallida sin detalle';
}
return [{ json: {
  subflujo: 'registrar_error',
  recordId: ctx.recordId,
  idea: ctx.idea,
  modulo,
  mensaje: String(mensaje).slice(0, 1000),
  cfg: ctx.cfg,
} }];

